extraStyle:
.contact-form { display: grid; gap: 0.85rem; margin-top: 1rem; }
.contact-form label { display: grid; gap: 0.35rem; font-weight: 600; font-size: 0.9rem; }
.contact-form input,
.contact-form textarea {
  width: 100%;
  border-radius: 10px;
  border: 1px solid var(--border);
  background: color-mix(in srgb, var(--bg) 70%, var(--surface));
  color: var(--text);
  font: inherit;
  padding: 0.7rem 0.8rem;
}
.contact-form textarea { min-height: 9rem; resize: vertical; }
.form-status { min-height: 1.2rem; color: var(--muted); font-size: 0.88rem; }
.form-status.error { color: #c62828; }
.form-status.ok { color: #2e7d32; }
